#pragma once
#include "domain/battle_replay.h"
#include <QRegularExpression>

// Hide only placeholders generated by our parser. Never remove numbers from
// official names, attributes, descriptions or the underlying record identity.
inline QString replayPublicFighterNameText(QString name) {
  static const QRegularExpression unresolved(QStringLiteral("^原名待核实 \\[[^\\]]*\\]$"));
  return name.isEmpty() || unresolved.match(name).hasMatch() ? QStringLiteral("原名待确认") : name;
}

inline QString replayPublicReferenceName(const QJsonObject& catalog, const QString& section, const QString& id) {
  if (section == QStringLiteral("pets")) return replayPublicFighterNameText(BattleReplay::petName(catalog, id));
  const auto entry = catalog[section].toObject()[id].toObject();
  const auto name = entry[section == QStringLiteral("skills") ? QStringLiteral("name") : QStringLiteral("nm")].toString().trimmed();
  if (!name.isEmpty()) return name;
  if (section == QStringLiteral("skills")) return QStringLiteral("技能名称待确认");
  if (section == QStringLiteral("attributes")) return QStringLiteral("属性名称待确认");
  return entry.isEmpty() ? QStringLiteral("效果名称未收录") : QStringLiteral("未命名效果");
}

// A battle-local origin is not a global skin mapping. Use its verified original
// name with an explicit role, while keeping the current race and catalog intact.
inline QString replayFighterEvidenceName(const BattleReplay::Fighter& fighter, const QJsonObject& catalog) {
  const auto pets = catalog[QStringLiteral("pets")].toObject();
  const auto identity = pets[fighter.raceId].toObject()[QStringLiteral("identity")].toObject();
  if (identity[QStringLiteral("status")].toString() != QStringLiteral("unresolved") ||
      fighter.originFighterKey.isEmpty() || fighter.originPath.isEmpty()) return BattleReplay::fighterName(fighter);
  const auto origin = pets[fighter.originRaceId].toObject()[QStringLiteral("identity")].toObject();
  const auto status = origin[QStringLiteral("status")].toString();
  const auto name = origin[QStringLiteral("canonicalName")].toString();
  if (name.isEmpty() || (status != QStringLiteral("native") && status != QStringLiteral("skin")))
    return BattleReplay::fighterName(fighter);
  if (fighter.originRelation == QStringLiteral("chaser")) return name + QStringLiteral("（追击体）");
  if (fighter.originRelation == QStringLiteral("transform")) return name + QStringLiteral("（变身后）");
  return BattleReplay::fighterName(fighter);
}

inline QString replayFighterName(const BattleReplay::Fighter& fighter, const QJsonObject& catalog) {
  return replayPublicFighterNameText(replayFighterEvidenceName(fighter, catalog));
}

// A definition link follows only the same recorded identity relationships as
// the battle inspector. A model/resource transFromRaceId is not such a link.
inline QString replayFighterPublicDefinitionRace(const BattleReplay::Fighter& fighter, const QJsonObject& catalog) {
  bool valid=false;
  const auto recorded=BattleReplay::valueText(fighter.raw.value(QStringLiteral("oRaceId"))).toLongLong(&valid);
  if (valid && recorded>0 && recorded<=2147483647) return QString::number(recorded);
  const auto pets=catalog.value(QStringLiteral("pets")).toObject();
  const auto identity=pets.value(fighter.raceId).toObject().value(QStringLiteral("identity")).toObject();
  if (identity.value(QStringLiteral("status")).toString()==QStringLiteral("unresolved") &&
      !fighter.originFighterKey.isEmpty() && !fighter.originPath.isEmpty() &&
      (fighter.originRelation==QStringLiteral("chaser") || fighter.originRelation==QStringLiteral("transform"))) {
    const auto original=pets.value(fighter.originRaceId).toObject().value(QStringLiteral("identity")).toObject();
    const auto status=original.value(QStringLiteral("status")).toString();
    if ((status==QStringLiteral("native") || status==QStringLiteral("skin")) && !original.value(QStringLiteral("canonicalName")).toString().isEmpty())
      return fighter.originRaceId;
  }
  return fighter.raceId;
}

inline QString replayFighterNameEvidence(const BattleReplay::Fighter& fighter, const QJsonObject& catalog) {
  if (replayFighterEvidenceName(fighter, catalog) == BattleReplay::fighterName(fighter)) return {};
  const auto officialName = catalog[QStringLiteral("pets")].toObject()[fighter.raceId].toObject()[QStringLiteral("name")].toString();
  return QStringLiteral("本场按已记录的%1原名显示；当前官方形态名：%2 [%3]。该形态尚无经过验证的全局原名对应，不把追击或变身关系当作换肤关系。\n关联依据：%4")
    .arg(fighter.originRelation == QStringLiteral("chaser") ? QStringLiteral("追击本体") : QStringLiteral("变身来源"),
      officialName, fighter.raceId, fighter.originPath);
}
